const fs = require('fs');

function solve() {
    const data = fs.readFileSync('/dev/stdin', 'utf8').trim().split('\n');
    const lines = data.filter(line => line.trim() !== '');

    if (lines.length < 2) return;

    const s = lines[0].trim();
    const hand = lines[1].trim().split(' ');

    const match = (a, b) => a[0] === b[0] || a[1] === b[1];

    const result = hand.some(card => match(s, card)) ? "YES" : "NO";
    console.log(result);
}

solve();

